INSERT IGNORE INTO `forge_exercises` (`slug`, `name`, `category`, `muscleGroup`, `difficulty`, `equipment`, `durationMinutes`, `description`, `benefits`, `formInstructions`, `commonMistakes`, `correctMediaUrl`, `wrongMediaUrl`) VALUES
('goblet-squat', 'Goblet Squat', 'Strength', 'Quads · Glutes', 'Beginner', 'Dumbbells', '5', 'A squat variation that builds lower-body strength while keeping the load close to your centre.', 'Leg strength · Hip control · Everyday lifting confidence', 'Hold one weight at your chest. Set feet about shoulder-width. Sit between your hips, keep your whole foot grounded, then stand tall without rushing.', 'Heels lifting · Knees collapsing inward · Dropping faster than you can control', NULL, NULL),
('romanian-deadlift', 'Romanian Deadlift', 'Strength', 'Hamstrings · Glutes', 'Intermediate', 'Dumbbells', '6', 'A hinge pattern for building strength through the back of the legs and hips.', 'Hip-hinge skill · Posterior-chain strength · Carryover to daily tasks', 'Hold weights close to your legs. Soften your knees, send hips back, keep your spine long, and stand by driving the floor away.', 'Rounding the back · Turning it into a squat · Letting weights drift away from the legs', NULL, NULL),
('incline-push-up', 'Incline Push-Up', 'Strength', 'Chest · Shoulders · Arms', 'Beginner', 'Bench', '4', 'An adjustable push-up variation. A higher hand position makes the movement easier to scale.', 'Upper-body pushing strength · Trunk control · Scalable progression', 'Place hands on a stable raised surface. Keep your body in one long line, lower your chest toward your hands, then press away.', 'Hips sagging · Elbows flaring straight out · Choosing an unstable surface', NULL, NULL),
('glute-bridge', 'Glute Bridge', 'Strength', 'Glutes · Hamstrings', 'Beginner', 'Bodyweight', '4', 'A floor-based hip extension exercise with a simple setup and adjustable range.', 'Hip extension · Glute activation · Accessible lower-body training', 'Lie on your back with feet planted. Gently brace your middle, press through the feet, lift your hips, pause, and lower with control.', 'Overarching the lower back · Pushing only through the toes · Rushing the lowering phase', NULL, NULL),
('dumbbell-row', 'Dumbbell Row', 'Strength', 'Back · Biceps', 'Beginner', 'Dumbbells', '5', 'A single-arm pulling movement that trains the upper back with support from a bench or sturdy surface.', 'Pulling strength · Shoulder control · Balanced upper-body work', 'Support one hand on a stable bench. Keep your back long, pull the weight toward your hip, then lower until the arm is comfortably long.', 'Twisting the torso · Shrugging the shoulder · Using momentum to lift', NULL, NULL),
('overhead-press', 'Overhead Press', 'Strength', 'Shoulders · Arms', 'Intermediate', 'Dumbbells', '5', 'A controlled press that builds shoulder and arm strength through a comfortable range.', 'Pressing strength · Shoulder coordination · Functional reaching', 'Start with weights near shoulder height. Brace gently, press overhead within a pain-free range, then return slowly to the start.', 'Arching the lower back · Rushing the descent · Forcing a range that feels uncomfortable', NULL, NULL),
('reverse-lunge', 'Reverse Lunge', 'Strength', 'Quads · Glutes', 'Intermediate', 'Bodyweight', '5', 'A step-back lunge that can be scaled with a shorter range or light hand support.', 'Single-leg strength · Balance · Hip and knee coordination', 'Stand near a support if helpful. Step one foot back, lower only as far as comfortable, then press through the front foot to return.', 'Rushing the step · Losing balance by narrowing stance · Forcing depth', NULL, NULL),
('dead-bug', 'Dead Bug', 'Core', 'Core', 'Beginner', 'Bodyweight', '4', 'A floor-based core exercise that coordinates arm and leg movement with steady breathing.', 'Trunk control · Coordination · Breath-led movement', 'Lie on your back with knees bent over hips. Exhale gently, lower opposite arm and leg only as far as you can keep control, then switch.', 'Holding your breath · Moving too far too soon · Letting the lower back arch sharply', NULL, NULL),
('plank', 'Forearm Plank', 'Core', 'Core · Shoulders', 'Beginner', 'Bodyweight', '3', 'A static trunk-strength exercise with options to use knees or an elevated surface.', 'Trunk endurance · Shoulder stability · Full-body tension', 'Place forearms down and make a steady line from head to hips. Breathe normally and finish the hold before your position changes.', 'Holding your breath · Letting hips sag · Staying in the position after form slips', NULL, NULL),
('step-up', 'Step-Up', 'Strength', 'Quads · Glutes', 'Beginner', 'Bench', '5', 'A practical step-up pattern using a stable, low platform and a pace that feels controlled.', 'Leg strength · Balance · Confidence on stairs', 'Use a low, stable step. Place the whole foot on it, press through that foot to rise, then step down with control. Hold a rail if needed.', 'Using a step that is too high · Pushing off the trailing foot · Letting the knee collapse inward', NULL, NULL);
INSERT IGNORE INTO `forge_programs` (`slug`, `name`, `description`, `difficulty`, `durationWeeks`, `equipment`, `sampleWorkouts`) VALUES
('foundation', 'Foundation', 'Build movement confidence with clear, repeatable sessions and room to progress at your pace.', 'Beginner', '4', 'Bodyweight · Optional dumbbells', '["Grounded strength · 20 min","Move and reset · 15 min","Everyday legs · 25 min"]'),
('strength', 'Strength', 'Progressive resistance training that prioritizes capable movement over appearance.', 'Beginner to intermediate', '6', 'Dumbbells · A stable bench', '["Full-body strength · 30 min","Hinge and carry · 25 min","Upper-body foundations · 20 min"]'),
('mobility', 'Mobility', 'A practical sequence for moving comfortably, exploring range and taking a breath between busy days.', 'All levels', '3', 'Mat · Optional support', '["Hips and ankles · 15 min","Spine in motion · 10 min","Full-body reset · 20 min"]'),
('life-stage', 'Life Stage', 'Flexible training choices that respect changing schedules, energy and individual needs.', 'Adaptable', '4', 'Bodyweight · Optional dumbbells', '["Choose your pace · 20 min","Strength, scaled · 15 min","Restore and move · 10 min"]');
INSERT IGNORE INTO `forge_meals` (`name`, `category`, `description`, `ingredients`, `prepMinutes`) VALUES
('Dal, rice & greens', 'Everyday plate', 'A familiar, flexible meal with lentils, rice and whichever greens are easy to find.', 'Dal · rice · spinach or seasonal greens · lemon', '25'),
('Paneer & vegetable wrap', 'Quick lunch', 'A warm wrap with paneer, crunchy vegetables and a simple yogurt or chutney spread.', 'Paneer · roti · cucumber · tomato · yogurt', '15'),
('Egg bhurji toast', 'Breakfast', 'Soft spiced eggs on toast, with fruit or leftover vegetables alongside if you like.', 'Eggs · onion · tomato · toast · coriander', '12'),
('Chana salad bowl', 'Make-ahead', 'Chickpeas with chopped vegetables, herbs and lemon; easy to adapt to what is on hand.', 'Chana · cucumber · tomato · lemon · herbs', '15'),
('Curd, fruit & nuts', 'Snack', 'A no-fuss combination for the moments between meals. Use the fruit you already have.', 'Curd · seasonal fruit · a small handful of nuts', '5'),
('Tofu & rice stir-fry', 'Dinner', 'A quick pan of tofu and vegetables served with rice, with seasoning to suit your table.', 'Tofu · mixed vegetables · rice · soy or spices', '20');
